import base64,hashlib,json,os,shlex,subprocess,sys
from pathlib import Path

prefix='/tmp/canoli-brush-wet-core-'
path=lambda suffix:Path(prefix+suffix)
digest=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def verify():
    result={}
    for kind,manifest in [('frozen',path('frozen.json')),('release',path('release.json')),('generated',path('generated.json')),('prior',Path('/tmp/canoli-brush-mixer-baseline')/'prior-evidence.json')]:
        values=json.loads(manifest.read_text());changed=[name for name,sha in values.items() if not Path(name).is_file() or digest(name)!=sha];assert not changed,(kind,changed);result[kind]=len(values)
    assert digest('public/wasm/pixels.wasm')==digest('dist/wasm/pixels.wasm')
    return result
def specs(suites):
    for suite in suites:
        yield from suite.get('specs',[])
        yield from specs(suite.get('suites',[]))
mode=sys.argv[1]
if mode=='verify':print(verify())
elif mode=='catalog':
    args=['npx','playwright','test',*path('browser-files.txt').read_text().split(),'--list','--reporter=json']
    with path('browser-catalog.json').open('w') as output:subprocess.run(args,stdout=output,check=True)
    report=json.loads(path('browser-catalog.json').read_text());cases=[(spec['file'],test.get('projectName',''),spec['title']) for spec in specs(report['suites']) for test in spec['tests']]
    print({'cases':len(cases),'files':len(set(case[0] for case in cases))})
elif mode in ['browser','production']:
    verify()
    files=path('browser-files.txt').read_text().split() if mode=='browser' else []
    args=['npx','playwright','test',*files,*(['--config','playwright.production.config.ts'] if mode=='production' else []),'--output',str(path(mode+'-accepted-results')),'--reporter=line,json']
    env=os.environ.copy();env.update(PLAYWRIGHT_CHROMIUM_EXECUTABLE='/home/kestrel/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',CANOLI_PSB_PYTHON='/tmp/canoli-psb-check/bin/python',CANOLI_PDF_PYTHON='/tmp/canoli-pdf-check/bin/python',PSD_READER_PYTHONPATH='/tmp/canoli-psb-check/lib/python3.10/site-packages',PLAYWRIGHT_JSON_OUTPUT_NAME=str(path(mode+'-final.json')))
    path(mode+'-command.txt').write_text(shlex.join(args)+'\n')
    with path(mode+'-final.log').open('w') as output:status=subprocess.run(args,stdout=output,stderr=subprocess.STDOUT,env=env).returncode
    path(mode+'-exit.json').write_text(json.dumps({'exitCode':status})+'\n');verify();print(mode,'exit',status,flush=True);assert status==0
    report=json.loads(path(mode+'-final.json').read_text());stats=report['stats'];assert stats['expected']>0 and stats['unexpected']==stats['flaky']==stats['skipped']==0
    keys=[];attachments=[]
    for spec in specs(report['suites']):
        for test in spec['tests']:
            results=test['results'];assert len(results)==1 and results[0]['status']=='passed' and results[0].get('retry',0)==0
            keys.append((spec['file'],test.get('projectName',''),spec['title']))
            for item in results[0].get('attachments',[]):
