                if data is not None:attachments.append(dict(file=spec['file'],test=spec['title'],name=item['name'],contentType=item.get('contentType'),sha256=hashlib.sha256(data).hexdigest(),**({'data':json.loads(data)} if item.get('contentType')=='application/json' else {'base64':base64.b64encode(data).decode()})))
